package com.dbstudio.cerebro.diagnostics

/**
 * Report generated by ErrorDoctor explaining a database failure in plain Spanish,
 * providing the root cause and actionable suggestions.
 */
data class DiagnosticReport(
    val title: String,
    val friendlyExplanation: String,
    val technicalSummary: String,
    val possibleCauses: List<String>,
    val suggestedActions: List<SuggestedAction>,
    val severity: DiagnosticSeverity = DiagnosticSeverity.ERROR
)

enum class DiagnosticSeverity {
    INFO,
    WARNING,
    ERROR,
    CRITICAL
}

data class SuggestedAction(
    val title: String,
    val description: String,
    val actionType: ActionType = ActionType.GENERAL_TIP
)

enum class ActionType {
    CREATE_PARENT_RECORD,
    FIX_DATA_TYPE,
    REMOVE_DUPLICATE_KEY,
    FILL_REQUIRED_FIELD,
    CLOSE_EXTERNAL_APP,
    CREATE_INTERMEDIATE_TABLE,
    GENERAL_TIP
}
